import { useSelector } from "react-redux";
import { userSelectors } from "../../store/selectors/userSelectors";

import "./UserData.css";

const UserData = () => {
  const users = useSelector(userSelectors);
  return <div>
    users.map((elm,i) => (
        <div key={i}>
          <p >{elm.name}</p>
          <img src={elm.file} alt="" />
        </div>
      ))}
  </div>;
};

export default UserData;
